import math
from mpi4py import MPI
import sys

def householder_tridiag(A):
    n = len(A)
    SX = [0.0] * n
    for I in range(n-2):
        # Compute SX array
        for K in range(I, n):
            SX[K] = A[n-1][I] * A[n-1][K]
        for J in range(n-1, I, -1):
            SX[I] += A[J][I] * A[J][I]
        for K in range(I+1, n):
            for J in range(n-1, K, -1):
                SX[K] += A[J][I] * A[J][K]
            for J in range(K-1, I, -1):
                SX[K] += A[J][I] * A[K][J]

        ALPHA = math.sqrt(SX[I])
        if A[I+1][I] != 0:
            BETA = 1.0 / ALPHA
            for J in range(I+2, n):
                A[J][I] *= BETA
            SX[I] = A[I+1][I] * BETA + math.copysign(1.0, A[I+1][I])
            A[I+1][I] = ALPHA
            G = 1.0 / abs(SX[I])
            SX2 = 0.0
            for K in range(I+2, n):
                SX[K] = SX[K] * BETA * G + math.copysign(A[K][I+1], SX[I])
                SX2 += SX[K] * A[K][I]
            SX2 = G * SX2
            for K in range(I+2, n):
                A[K][K] = A[K][K] - 2 * A[K][I] * SX[K] + SX2 * A[K][I] ** 2
                for J in range(K+1, n):
                    A[J][K] = A[J][K] - A[J][I] * SX[K] - A[K][I] * SX[I] + SX2 * A[J][I] * A[K][I]
        else:
            if ALPHA != 0:
                BETA = 1.0 / ALPHA
                for J in range(I+2, n):
                    A[J][I] *= BETA
                SX[I] = -1.0
                A[I+1][I] = ALPHA
                G = 1.0
                SX2 = 0.0
                for K in range(I+2, n):
                    SX[K] = SX[K] * BETA * G + math.copysign(A[K][I+1], SX[I])
                    SX2 += SX[K] * A[K][I]
                SX2 = G * SX2
                for K in range(I+2, n):
                    A[K][K] = A[K][K] - 2 * A[K][I] * SX[K] + SX2 * A[K][I] ** 2
                    for J in range(K+1, n):
                        A[J][K] = A[J][K] - A[J][I] * SX[K] - A[K][I] * SX[I] + SX2 * A[J][I] * A[K][I]
            else:
                SX[I] = 1.0
    return A

def main():
    comm = MPI.COMM_WORLD
    rank = comm.Get_rank()
    size = comm.Get_size()

    # Example matrix size
    n = 10
    if rank == 0:
        # Generate a random symmetric matrix A of size n
        A = [[0.0]*n for _ in range(n)]
        for i in range(n):
            for j in range(i, n):
                val = math.sin(i+j)  # Example values
                A[i][j] = val
                A[j][i] = val
    else:
        A = [[0.0]*n for _ in range(n)]

    # Broadcast matrix A to all processes
    A = comm.bcast(A, root=0)

    # All processes compute the tridiagonal form (replicated computation)
    A_trid = householder_tridiag(A)

    # Output result on rank 0
    if rank == 0:
        print("Tridiagonal matrix (diagonal and subdiagonal):")
        for i in range(n):
            if i < n-1:
                print(f"A[{i},{i}] = {A_trid[i][i]:.6f}, A[{i+1},{i}] = {A_trid[i+1][i]:.6f}")
            else:
                print(f"A[{i},{i}] = {A_trid[i][i]:.6f}")

if __name__ == "__main__":
    main()
